/**
 * emergency-engine.ts —— 临期应急建议引擎（纯函数）
 *
 * 规则引擎，5 条确定性规则，命中即生成建议
 * 全部输出草稿态 proposal（type=emergency），用户确认才执行
 * 无 LLM 调用，每条建议都有明确的 rationale 可解释
 */
type TaskStatus = 'todo' | 'in_progress' | 'done' | 'blocked' | 'cancelled';
type TaskPriority = 'low' | 'medium' | 'high' | 'urgent';
interface EmergencyTask {
    id: string;
    title?: string;
    status: TaskStatus;
    progress: number;
    estimatedHours: number;
    dueDate?: Date;
    assigneeId?: string;
    priority: TaskPriority;
}
interface EmergencyDependency {
    id: string;
    fromTaskId: string;
    toTaskId: string;
    type: string;
}
interface MemberLoad {
    assigneeId: string;
    inProgressCount: number;
    totalHours: number;
}
export interface EmergencyInput {
    projectId: string;
    projectName?: string;
    tasks: EmergencyTask[];
    dependencies?: EmergencyDependency[];
    memberLoads?: MemberLoad[];
    now?: Date;
    focusAreas?: string[];
}
export type EmergencyActionType = 'rush' | 'reassign' | 'split' | 'de-prioritize' | 'extend_deadline' | 'freeze_scope';
export interface EmergencyAction {
    id: string;
    actionType: EmergencyActionType;
    title: string;
    rationale: string;
    impact: string;
    targetTaskIds: string[];
    targetAssigneeIds?: string[];
    effortHours?: number;
    riskReductionEstimate?: number;
}
export interface EmergencySuggestionResult {
    projectId: string;
    actions: EmergencyAction[];
    riskScoreBefore: number;
    riskScoreAfterEstimate: number;
    summary: string;
    generatedAt: Date;
}
/** 生成应急建议 */
export declare function generateEmergencySuggestions(input: EmergencyInput): EmergencySuggestionResult;
export {};
